void main() {
  // Cuckoo Hashing implementation in Dart (with basic integer keys/values)

  // Parameters
  const int tableSize = 11; // Size of each table
  const int maxKicks = 16;  // Maximum number of displacements before rehash

  // Two hash tables
  List<int?> table1 = List.filled(tableSize, null);
  List<int?> table2 = List.filled(tableSize, null);

  // Two hash functions (simple for demonstration)
  int hash1(int key) => key % tableSize;
  int hash2(int key) => (key ~/ tableSize) % tableSize;

  // Insert function
  bool insert(int key) {
    int curKey = key;
    int table = 0;
    for (int kick = 0; kick < maxKicks; ++kick) {
      if (table == 0) {
        int idx = hash1(curKey);
        if (table1[idx] == null) {
          table1[idx] = curKey;
          return true;
        } else if (table1[idx] == curKey) {
          // Key already present
          return true;
        } else {
          // Kick out
          int temp = table1[idx]!;
          table1[idx] = curKey;
          curKey = temp;
          table = 1;
        }
      } else {
        int idx = hash2(curKey);
        if (table2[idx] == null) {
          table2[idx] = curKey;
          return true;
        } else if (table2[idx] == curKey) {
          return true;
        } else {
          int temp = table2[idx]!;
          table2[idx] = curKey;
          curKey = temp;
          table = 0;
        }
      }
    }
    // Too many kicks, insertion failed (cycle detected)
    print('Failed to insert $key after $maxKicks displacements. Table may need rehashing.');
    return false;
  }

  // Search function
  bool contains(int key) {
    int idx1 = hash1(key);
    if (table1[idx1] == key) return true;
    int idx2 = hash2(key);
    if (table2[idx2] == key) return true;
    return false;
  }

  // Delete function
  bool remove(int key) {
    int idx1 = hash1(key);
    if (table1[idx1] == key) {
      table1[idx1] = null;
      return true;
    }
    int idx2 = hash2(key);
    if (table2[idx2] == key) {
      table2[idx2] = null;
      return true;
    }
    return false;
  }

  // Print both tables
  void printTables() {
    print('Table 1:');
    for (int i = 0; i < tableSize; ++i) {
      print('[$i]: ${table1[i]}');
    }
    print('Table 2:');
    for (int i = 0; i < tableSize; ++i) {
      print('[$i]: ${table2[i]}');
    }
  }

  // Test the cuckoo hash
  List<int> keysToInsert = [5, 20, 15, 7, 22, 45, 33, 17, 11, 13, 99, 27, 14];

  print('Inserting keys: $keysToInsert');
  for (var key in keysToInsert) {
    insert(key);
  }

  print('\nTables after insertion:');
  printTables();

  List<int> searchKeys = [7, 22, 14, 99, 100];
  print('\nSearching for keys: $searchKeys');
  for (var key in searchKeys) {
    print('Contains $key? ${contains(key)}');
  }

  print('\nRemoving key 22 and 7...');
  remove(22);
  remove(7);

  print('\nTables after removal:');
  printTables();

  print('\nTrying to insert 42...');
  insert(42);
  printTables();
}

