// A simple Dart program implementing a Quadtree for spatial indexing.
// This is a complete, compilable script with classes and a main function.

import 'dart:math' as math;

// Point class to represent 2D points.
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';
}

// Rectangle class to represent boundaries.
class Rectangle {
  final double x;
  final double y;
  final double width;
  final double height;

  Rectangle(this.x, this.y, this.width, this.height);

  // Check if this rectangle contains a point.
  bool contains(Point point) {
    return (point.x >= x - width &&
        point.x <= x + width &&
        point.y >= y - height &&
        point.y <= y + height);
  }

  // Check if this rectangle intersects with another rectangle.
  bool intersects(Rectangle range) {
    return !(range.x - range.width > x + width ||
        range.x + range.width < x - width ||
        range.y - range.height > y + height ||
        range.y + range.height < y - height);
  }

  @override
  String toString() => 'Rectangle($x, $y, $width, $height)';
}

// QuadTree class for spatial indexing.
class QuadTree {
  final Rectangle boundary;
  final int capacity;
  List<Point> points = [];
  QuadTree? northwest;
  QuadTree? northeast;
  QuadTree? southwest;
  QuadTree? southeast;
  bool divided = false;

  QuadTree(this.boundary, this.capacity);

  // Insert a point into the quadtree.
  void insert(Point point) {
    if (!boundary.contains(point)) {
      return;
    }

    if (points.length < capacity && !divided) {
      points.add(point);
    } else {
      if (!divided) {
        subdivide();
      }

      northwest?.insert(point);
      northeast?.insert(point);
      southwest?.insert(point);
      southeast?.insert(point);
    }
  }

  // Subdivide the quadtree into four quadrants.
  void subdivide() {
    double x = boundary.x;
    double y = boundary.y;
    double w = boundary.width / 2;
    double h = boundary.height / 2;

    northwest = QuadTree(Rectangle(x - w / 2, y - h / 2, w, h), capacity);
    northeast = QuadTree(Rectangle(x + w / 2, y - h / 2, w, h), capacity);
    southwest = QuadTree(Rectangle(x - w / 2, y + h / 2, w, h), capacity);
    southeast = QuadTree(Rectangle(x + w / 2, y + h / 2, w, h), capacity);

    // Redistribute existing points to children.
    for (var p in points) {
      northwest?.insert(p);
      northeast?.insert(p);
      southwest?.insert(p);
      southeast?.insert(p);
    }
    points.clear();
    divided = true;
  }

  // Query points within a given range.
  List<Point> query(Rectangle range, [List<Point>? found]) {
    found ??= [];
    if (!boundary.intersects(range)) {
      return found;
    }

    for (var p in points) {
      if (range.contains(p)) {
        found.add(p);
      }
    }

    if (divided) {
      northwest?.query(range, found);
      northeast?.query(range, found);
      southwest?.query(range, found);
      southeast?.query(range, found);
    }

    return found;
  }

  // Helper to print the quadtree structure for demonstration.
  void printTree([int level = 0]) {
    String indent = '  ' * level;
    print('$indent- Boundary: $boundary');
    print('$indent  Points: $points');
    if (divided) {
      print('$indent  Children:');
      northwest?.printTree(level + 1);
      northeast?.printTree(level + 1);
      southwest?.printTree(level + 1);
      southeast?.printTree(level + 1);
    }
  }
}

@pragma('vm:entry-point')
void main() {
  // Create a quadtree with a boundary of (0,0) to (400,400) and capacity 4.
  var boundary = Rectangle(0, 0, 200, 200);
  var qt = QuadTree(boundary, 4);

  // Insert some random points for demonstration.
  var random = math.Random();
  for (int i = 0; i < 20; i++) {
    var p = Point(
      random.nextDouble() * 400 - 200, // x from -200 to 200
      random.nextDouble() * 400 - 200, // y from -200 to 200
    );
    qt.insert(p);
    print('Inserted: $p');
  }

  // Print the quadtree structure.
  print('\nQuadTree Structure:');
  qt.printTree();

  // Query points in a sample range.
  var queryRange = Rectangle(0, 0, 50, 50);
  var foundPoints = qt.query(queryRange);
  print('\nPoints found in range $queryRange:');
  for (var p in foundPoints) {
    print(p);
  }
}

