import 'dart:math';
import 'dart:typed_data';

class BloomFilter {
  late int _size;
  late int _numHashes;
  late Uint8List _bits;
  late int _expectedItems;

  BloomFilter(int expectedItems, double falsePositiveRate) {
    _expectedItems = expectedItems;
    // Calculate optimal size m = - (n * ln(p)) / (ln(2)^2)
    _size = (-(expectedItems * log(falsePositiveRate)) /
            (log(2) * log(2)))
        .ceil();
    // Calculate optimal number of hashes k = (m/n) * ln(2)
    _numHashes = ((_size / expectedItems) * log(2)).round();
    _bits = Uint8List((_size + 7) ~/ 8);
  }

  int _hash(String item, int seed) {
    int hash = seed;
    for (var code in item.codeUnits) {
      hash = (hash * 31 + code) & 0xFFFFFFFF;
    }
    return hash;
  }

  void add(String item) {
    int hash1 = _hash(item, 0);
    int hash2 = _hash(item, 1);
    for (int i = 0; i < _numHashes; i++) {
      int index = (hash1 + i * hash2).abs() % _size;
      _bits[index ~/ 8] |= (1 << (index % 8));
    }
  }

  bool mightContain(String item) {
    int hash1 = _hash(item, 0);
    int hash2 = _hash(item, 1);
    for (int i = 0; i < _numHashes; i++) {
      int index = (hash1 + i * hash2).abs() % _size;
      if ((_bits[index ~/ 8] & (1 << (index % 8))) == 0) {
        return false;
      }
    }
    return true;
  }
}

