// A complete, compilable Dart program implementing simple in-app analytics tracking.
// This script simulates tracking user events in a console application, stores them in memory,
// and periodically "sends" them to a mock server (simulated by printing to console).
// In a real app, you'd replace the print with an HTTP post to an analytics endpoint.

@pragma('vm:entry-point')
void main() async {
  // In-memory storage for tracked events (event name -> count and details)
  Map<String, Map<String, dynamic>> analyticsData = {};

  // Function to track an event (defined inside main for simplicity)
  void trackEvent(String eventName, [Map<String, dynamic>? parameters]) {
    if (!analyticsData.containsKey(eventName)) {
      analyticsData[eventName] = {'count': 0, 'parameters': []};
    }
    analyticsData[eventName]!['count'] = (analyticsData[eventName]!['count'] as int) + 1;
    if (parameters != null) {
      analyticsData[eventName]!['parameters'].add(parameters);
    }
    print('Tracked event: $eventName with parameters: $parameters');
  }

  // Function to "send" analytics data (simulates sending to a server)
  Future<void> sendAnalytics() async {
    String jsonData = jsonEncode(analyticsData);
    print('Sending analytics data to server: $jsonData');
    // In a real app, use http package to POST this to an endpoint, e.g.:
    // await http.post(Uri.parse('https://analytics.example.com/track'), body: jsonData);
    // For this script, we just print and clear the data.
    analyticsData.clear();
  }

  // Simulate app lifecycle and user interactions
  print('App started. Tracking analytics...');

  // Track app open
  trackEvent('app_open', {'timestamp': DateTime.now().toIso8601String()});

  // Simulate some user actions
  await Future.delayed(Duration(seconds: 1));
  trackEvent('screen_view', {'screen': 'home', 'duration': 10});

  await Future.delayed(Duration(seconds: 1));
  trackEvent('button_click', {'button_id': 'login', 'user_id': '123'});

  await Future.delayed(Duration(seconds: 1));
  trackEvent('screen_view', {'screen': 'profile', 'duration': 5});

  await Future.delayed(Duration(seconds: 1));
  trackEvent('error_occurred', {'error_code': 404, 'message': 'Not found'});

  // Simulate periodic sending of analytics (e.g., every 5 seconds in a real app)
  await sendAnalytics();

  // Track app close
  trackEvent('app_close', {'session_duration': 5});
  await sendAnalytics();

  print('App closed. Analytics tracking complete.');
}

