    print('Usage: dart boyer_moore.dart <pattern> <text>');
    return;
  }

  final pattern = args[0];
  final text = args[1];

  // ---------- Helpers (all nested to keep only `main` at top level) ----------
  List<int> _buildBadCharTable(String pat) {
    // Covers the Basic Multilingual Plane (0–0xFFFF).
    const int alphabetSize = 0x10000;
    final table = List<int>.filled(alphabetSize, -1);
    for (var i = 0; i < pat.length; i++) {
      table[pat.codeUnitAt(i)] = i; // last occurrence of the character
    }
    return table;
  }

  void _buildGoodSuffixTables(
    String pat,
    List<int> suffix,      // length m
    List<bool> prefix,     // length m
  ) {
    final m = pat.length;
    for (var i = 0; i < m; i++) {
      suffix[i] = -1;
      prefix[i] = false;
    }

    // Walk pattern and record suffix/prefix information.
    for (var i = 0; i < m - 1; i++) {
      var j = i;
      var k = 0; // length of suffix matched so far

      // Move left from position i, comparing to the right end of pattern.
      while (j >= 0 && pat.codeUnitAt(j) == pat.codeUnitAt(m - 1 - k)) {
        j--;
        k++;
        suffix[k - 1] = j + 1; // start index of suffix of length k
      }

      if (j == -1) {
        // Matched a prefix of pattern that is also a suffix.
        prefix[k - 1] = true;
      }
    }
  }

  int _goodSuffixShift(
    int j,                 // mismatching position in pattern
    int m,                 // pattern length
    List<int> suffix,
    List<bool> prefix,
  ) {
    final k = m - 1 - j; // length of the matched suffix (pattern[j+1 .. m-1])
    if (k == 0) return 0; // no suffix matched, let bad-char rule decide

    // Case 1: Found another occurrence of that suffix inside the pattern.
    if (suffix[k - 1] != -1) {
      return j - suffix[k - 1] + 1;
    }

    // Case 2: Look for the longest prefix of pattern that matches
    // a suffix of the already matched part.
    for (var r = j + 2; r < m; r++) {
      if (prefix[m - r]) {
        return r;
      }
    }

    // Case 3: No substring or prefix matched – shift by pattern length.
    return m;
  }

  List<int> _boyerMooreSearch(String txt, String pat) {
    final n = txt.length;
    final m = pat.length;
    if (m == 0 || n < m) return const [];

    final badChar = _buildBadCharTable(pat);
    final suffix = List<int>.filled(m, -1);
    final prefix = List<bool>.filled(m, false);
    _buildGoodSuffixTables(pat, suffix, prefix);

    final matches = <int>[];
    var i = 0; // index in text

    while (i <= n - m) {
      var j = m - 1; // index in pattern

      // Scan pattern from right to left.
      while (j >= 0 && pat.codeUnitAt(j) == txt.codeUnitAt(i + j)) {
        j--;
      }

      if (j < 0) {
        // Full match found.
        matches.add(i);
        i += m; // shift past the found occurrence
        continue;
      }

      // Bad-character rule.
      final badStep = j - badChar[txt.codeUnitAt(i + j)];
      // Good-suffix rule.
      final gsStep = _goodSuffixShift(j, m, suffix, prefix);

      i += (badStep > gsStep ? badStep : gsStep).clamp(1, m);
    }

    return matches;
  }

  // ---------- Run search & report ----------
  final positions = _boyerMooreSearch(text, pattern);
  if (positions.isEmpty) {
    print('No occurrence of "$pattern" found.');
  } else {
    print('Found "${pattern}" at position(s): ${positions.join(', ')}');
  }
}

