  IntOp subtract = (a, b) => a - b;
  IntOp multiply = (a, b) => a * b;
  IntOp power    = (a, b) => pow(a, b).toInt();

  const int x = 6;
  const int y = 4;

  print('Demonstrating IntOp typedefs:');
  print('$x + $y = ${add(x, y)}');
  print('$x - $y = ${subtract(x, y)}');
  print('$x * $y = ${multiply(x, y)}');
  print('$x ^ $y = ${power(x, y)}');

  // Using the generic Predicate typedef.
  Predicate<int> isEven = (n) => n.isEven;
  final numbers = List<int>.generate(10, (i) => i);
  final evens = numbers.where(isEven);

  print('\nDemonstrating Predicate<int> typedef:');
  print('Original list : $numbers');
  print('Even numbers  : $evens');
}

