import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Nested wildcard-matching routine supporting
  //  *  → any sequence (including empty)
  //  ?  → any single character
  bool matches(String pattern, String text) {
    final pLen = pattern.length;
    final tLen = text.length;

    // dp[i][j] is true when pattern[0‥i) matches text[0‥j)
    final dp = List.generate(
        pLen + 1, (_) => List<bool>.filled(tLen + 1, false, growable: false),
        growable: false);

    dp[0][0] = true; // Empty pattern matches empty text.

    // Deal with leading '*'s: they can match an empty string.
    for (var i = 1; i <= pLen && pattern[i - 1] == '*'; ++i) {
      dp[i][0] = true;
    }

    for (var i = 1; i <= pLen; ++i) {
      final pChar = pattern[i - 1];
      for (var j = 1; j <= tLen; ++j) {
        final tChar = text[j - 1];

        if (pChar == '*') {
          // '*' matches zero chars (dp[i-1][j]) or one more char (dp[i][j-1])
          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        } else if (pChar == '?' || pChar == tChar) {
          // Current chars match; inherit previous state.
          dp[i][j] = dp[i - 1][j - 1];
        }
      }
    }
    return dp[pLen][tLen];
  }

  // Simple CLI usage: `dart run wildcard.dart <pattern> <text>`
  if (args.length < 2) {
    stdout.writeln('Usage: dart run wildcard.dart <pattern> <text>');
    stdout.writeln("Wildcards:  ? = any single char,  * = any sequence.");
    stdout.writeln('Example:  dart run wildcard.dart "*.dart" "main.dart"');
    exit(64); // EX_USAGE
  }

  final pattern = args[0];
  final text = args[1];
  stdout.writeln(matches(pattern, text) ? 'MATCH' : 'NO MATCH');
}

