//
// A tiny file-download manager that supports
//  • multiple simultaneous downloads               (default 3)
//  • configurable output directory                 (-d / --dir <path>)
//  • configurable parallelism                      (-c / --concurrent <n>)
//  • very small dependency footprint (only dart:io)
//
// Example
//   dart run download_manager.dart \
//        -c 4 -d downloads \
//        https://example.com/a.jpg https://example.com/b.jpg
//
import 'dart:async';
import 'dart:io';

@pragma('vm:entry-point')
Future<void> main(List<String> args) async {
  /* ───────────────────── CLI parsing ───────────────────── */
  if (args.isEmpty ||
      args.contains('-h') ||
      args.contains('--help')) {
    stdout
      ..writeln('Usage: dart run download_manager.dart [options] <url> [url] …')
      ..writeln('Options:')
      ..writeln('  -d, --dir <path>         Directory to save files (default: .)')
      ..writeln('  -c, --concurrent <n>     Concurrent downloads     (default: 3)')
      ..writeln('  -h, --help               Show this help and exit');
    exit(0);
  }

  int concurrency = 3;
  Directory outDir = Directory.current;
  final urls = <String>[];

  for (var i = 0; i < args.length; i++) {
    final arg = args[i];
    switch (arg) {
      case '-c':
      case '--concurrent':
        if (++i >= args.length) {
          stderr.writeln('Missing value for $arg');
          exit(64);
        }
        concurrency = int.tryParse(args[i]) ?? concurrency;
        if (concurrency < 1) concurrency = 1;
        break;
      case '-d':
      case '--dir':
        if (++i >= args.length) {
          stderr.writeln('Missing value for $arg');
          exit(64);
        }
        outDir = Directory(args[i]);
        if (!outDir.existsSync()) outDir.createSync(recursive: true);
        break;
      default:
        urls.add(arg);
    }
  }
  if (urls.isEmpty) {
    stderr.writeln('No URLs supplied.');
    exit(64);
  }

  /* ─────────────────── download helpers ─────────────────── */
  final client = HttpClient()..maxConnectionsPerHost = concurrency;

  Future<void> download(String url) async {
    final uri = Uri.parse(url);
    String name = uri.pathSegments.isNotEmpty && uri.pathSegments.last.isNotEmpty
        ? uri.pathSegments.last
        : 'file_${DateTime.now().millisecondsSinceEpoch}';

    // Prevent accidental overwrite.
    var file = File('${outDir.path}${Platform.pathSeparator}$name');
    var suffix = 1;
    while (file.existsSync()) {
      name = '${uri.pathSegments.last}($suffix)';
      file = File('${outDir.path}${Platform.pathSeparator}$name');
      suffix++;
    }

    stdout.writeln('↗️  Start  $url');
    try {
      final resp = await (await client.getUrl(uri)).close();
      if (resp.statusCode != HttpStatus.ok) {
        stderr.writeln('❌ $url  (HTTP ${resp.statusCode})');
        return;
      }

      final total = resp.contentLength;
      var received = 0;
      final sink = file.openWrite();
      await for (final chunk in resp) {
        sink.add(chunk);
        received += chunk.length;
        if (total > 0) {
          final pct = (received / total) * 100;
          stdout.write('\r📥 $name  ${pct.toStringAsFixed(1)} %');
        } else {
          stdout.write('\r📥 $name  ${received} bytes');
        }
      }
      await sink.close();
      stdout.writeln('\r✅ Done   $name (${received} bytes)');
    } catch (e) {
      stderr.writeln('\n❌ Error  downloading $url  —  $e');
      if (file.existsSync()) file.deleteSync();
    }
  }

  /* ───────────── simple fixed-width download pool ────────── */
  var next = 0;
  Future<void> worker() async {
    while (true) {
      String? url;
      if (next < urls.length) url = urls[next++];
      if (url == null) return;
      await download(url);
    }
  }

  final timers = List<Future<void>>.generate(
      concurrency < urls.length ? concurrency : urls.length, (_) => worker());

  await Future.wait(timers);
  client.close(force: false);

  stdout.writeln('\n🏁 All downloads finished.');
}

