// in_app_notification_center.dart
//
// A minimal, self-contained demonstration of an in-app notification
// center.  Run with:
//
//   dart run in_app_notification_center.dart
//
// The program keeps everything in one file and exposes only the
// ‘main’ function to the outside world, as requested.

import 'dart:async';

/// Immutable model object that represents a single in-app notification.
class AppNotification {
  final int id;
  final String title;
  final String body;
  final DateTime timestamp;
  bool read = false;

  AppNotification({
    required this.id,
    required this.title,
    required this.body,
    DateTime? timestamp,
  }) : timestamp = timestamp ?? DateTime.now();

  @override
  String toString() =>
      '[${read ? '✓' : '•'}] #$id  $title  –  $body  '
      '(${timestamp.toIso8601String()})';
}

/// Simple publish/subscribe notification center.
///
/// Clients call `add()` to push notifications; UI layers subscribe to
/// `onNotification` to react when new notifications arrive.
class NotificationCenter {
  final List<AppNotification> _notifications = <AppNotification>[];
  final StreamController<AppNotification> _controller =
      StreamController<AppNotification>.broadcast();
  int _nextId = 1;

  /// Stream that emits each notification as soon as it is added.
  Stream<AppNotification> get onNotification => _controller.stream;

  /// All notifications (newest first).
  List<AppNotification> get all => List.unmodifiable(_notifications);

  /// Unread notifications.
  List<AppNotification> get unread =>
      _notifications.where((n) => !n.read).toList(growable: false);

  int get unreadCount => unread.length;

  /// Push a new notification.
  AppNotification add(String title, String body) {
    final n = AppNotification(id: _nextId++, title: title, body: body);
    _notifications.insert(0, n);
    _controller.add(n);
    return n;
  }

  /// Mark a notification as read.
  void markAsRead(int id) {
    final n = _notifications
        .firstWhere((e) => e.id == id, orElse: () => throw ArgumentError(
              'Notification with id=$id not found',
            ));
    n.read = true;
  }

  /// Remove a notification permanently.
  void remove(int id) =>
      _notifications.removeWhere((n) => n.id == id);

  void dispose() => _controller.close();
}

@pragma('vm:entry-point')
Future<void> main() async {
  // Instantiate centre and hook up a listener (simulated UI layer).
  final center = NotificationCenter();
  final sub = center.onNotification.listen(
    (n) => print('🔔  New notification: "${n.title}" – ${n.body}'),
  );

  // Push a couple of immediate notifications.
  center
    ..add('Welcome', 'Thanks for trying our app ✨')
    ..add('Achievement', 'You completed the tutorial 🎉');

  // Push one after a delay – as if from a network call.
  Future.delayed(
    const Duration(seconds: 1),
    () => center.add('Update available', 'Version 2.0 can now be installed'),
  );

  // Simulate user actions that read/delete notifications.
  Future.delayed(const Duration(seconds: 2), () {
    center.markAsRead(1);
    print('User read notification #1.  Unread count: ${center.unreadCount}');
  });

  Future.delayed(const Duration(seconds: 3), () {
    center.remove(2);
    print('User dismissed notification #2.  Remaining: ${center.all.length}');
  });

  // After 4 s dump state and exit.
  await Future.delayed(const Duration(seconds: 4));
  print('\n--- Notification Center Dump ---');
  center.all.forEach(print);

  await sub.cancel();
  center.dispose();
}

