    if (num < 0) {
      negativeNumbers.add(-num); // Convert to positive for sorting
    } else {
      positiveNumbers.add(num);
    }
  }

  // Sort positive numbers
  if (positiveNumbers.isNotEmpty) {
    // Find the maximum number to determine number of digits
    int maxNum = positiveNumbers[0];
    for (int i = 1; i < positiveNumbers.length; i++) {
      if (positiveNumbers[i] > maxNum) {
        maxNum = positiveNumbers[i];
      }
    }

    // Perform radix sort on positive numbers
    int exp = 1;
    while (maxNum ~/ exp > 0) {
      // Counting sort for current digit
      List<int> output = List<int>.filled(positiveNumbers.length, 0);
      List<int> count = List<int>.filled(10, 0);

      // Count occurrences of each digit
      for (int i = 0; i < positiveNumbers.length; i++) {
        int digit = (positiveNumbers[i] ~/ exp) % 10;
        count[digit]++;
      }

      // Calculate cumulative count
      for (int i = 1; i < 10; i++) {
        count[i] += count[i - 1];
      }

      // Build output array
      for (int i = positiveNumbers.length - 1; i >= 0; i--) {
        int digit = (positiveNumbers[i] ~/ exp) % 10;
        output[count[digit] - 1] = positiveNumbers[i];
        count[digit]--;
      }

      // Copy output array to positiveNumbers
