    for (int color = 0; color < maxColors; color++) {
      if (isSafeColor(vertex, color, graph, colors)) {
        colors[vertex] = color;

        // Recur for next vertex
        if (graphColoringUtil(vertex + 1, graph, colors, maxColors)) {
