@pragma('vm:entry-point')
void main() {
  // Example graph represented as adjacency list
  // Graph: 0 -> 1 -> 2 -> 0 (cycle)
  //        1 -> 3
  //        3 -> 4
  //        4 -> 5 -> 3 (cycle)
  //        6 -> 7 -> 6 (cycle)
  //        7 -> 8

  final Map<int, List<int>> graph = {
    0: [1],
    1: [2, 3],
    2: [0],
    3: [4],
    4: [5],
    5: [3],
    6: [7],
    7: [6, 8],
    8: [],
  };

  // Tarjan's algorithm state
  int index = 0;
  final List<int> stack = [];
  final Map<int, int> indices = {};
  final Map<int, int> lowlinks = {};
  final Set<int> onStack = {};
  final List<List<int>> sccs = [];

  // Tarjan's strongconnect function
  void strongconnect(int v) {
    // Set the depth index for v to the smallest unused index
    indices[v] = index;
    lowlinks[v] = index;
    index++;
    stack.add(v);
    onStack.add(v);

    // Consider successors of v
    if (graph.containsKey(v)) {
      for (int w in graph[v]!) {
        if (!indices.containsKey(w)) {
          // Successor w has not yet been visited; recurse on it
          strongconnect(w);
          lowlinks[v] = lowlinks[v]! < lowlinks[w]! ? lowlinks[v]! : lowlinks[w]!;
        } else if (onStack.contains(w)) {
          // Successor w is in stack S and hence in the current SCC
          lowlinks[v] = lowlinks[v]! < indices[w]! ? lowlinks[v]! : indices[w]!;
        }
      }
    }

    // If v is a root node, pop the stack and print an SCC
    if (lowlinks[v] == indices[v]) {
      final List<int> scc = [];
      int w;
      do {
        w = stack.removeLast();
        onStack.remove(w);
        scc.add(w);
      } while (w != v);
      sccs.add(scc);
    }
  }

  // Main algorithm: call strongconnect for each unvisited vertex
  for (int v in graph.keys) {
    if (!indices.containsKey(v)) {
      strongconnect(v);
    }
  }

  // Print results
  print('Strongly Connected Components found: ${sccs.length}');
  for (int i = 0; i < sccs.length; i++) {
    print('SCC ${i + 1}: ${sccs[i]}');
  }

  // Test with another graph
  print('\n--- Testing with another graph ---');

  final Map<int, List<int>> graph2 = {
    0: [1, 2],
    1: [2],
    2: [3],
    3: [1],
    4: [3, 5],
    5: [4],
  };

  // Reset state for new graph
  index = 0;
  stack.clear();
  indices.clear();
  lowlinks.clear();
  onStack.clear();
  sccs.clear();

