      for (int i = 0; i < dataPoints.length; i++) {
        if (clusterAssignments[i] == j) {
          for (int dim = 0; dim < dataPoints[i].length; dim++) {
            newCentroid[dim] += dataPoints[i][dim];
          }
          count++;
        }
      }

      if (count > 0) {
        for (int dim = 0; dim < newCentroid.length; dim++) {
          centroids[j][dim] = newCentroid[dim] / count;
        }
      }
    }
  }

  // Print results
