  print('Number of clusters: $k');
  print('\nFinal Centroids:');
  for (int i = 0; i < centroids.length; i++) {
    print('Centroid ${i + 1}: [${centroids[i].map((v) => v.toStringAsFixed(2)).join(', ')}]');
  }

  print('\nCluster Assignments:');
  for (int i = 0; i < k; i++) {
    List<List<double>> clusterPoints = [];
    for (int j = 0; j < dataPoints.length; j++) {
      if (clusterAssignments[j] == i) {
        clusterPoints.add(dataPoints[j]);
      }
    }
    print('\nCluster ${i + 1} (${clusterPoints.length} points):');
    for (var point in clusterPoints) {
      print('  [${point.map((v) => v.toStringAsFixed(1)).join(', ')}]');
    }
  }

  // Calculate and print Within-Cluster Sum of Squares (WCSS)
  double wcss = 0.0;
  for (int i = 0; i < dataPoints.length; i++) {
    double distance = 0.0;
    int cluster = clusterAssignments[i];
    for (int dim = 0; dim < dataPoints[i].length; dim++) {
      double diff = dataPoints[i][dim] - centroids[cluster][dim];
      distance += diff * diff;
    }
    wcss += distance;
  }
  print('\nWithin-Cluster Sum of Squares (WCSS): ${wcss.toStringAsFixed(2)}');
}
