import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Sample data: y = 2x + 3
  List<double> x = [1, 2, 3, 4, 5];
  List<double> y = [5, 7, 9, 11, 13];

  // Hyperparameters
  double learningRate = 0.01;
  int iterations = 1000;

  // Model parameters (initialized to zero)
  double m = 0.0; // slope
  double b = 0.0; // intercept

  int n = x.length;

  // Mean Squared Error cost function
  double computeCost() {
    double totalError = 0.0;
    for (int i = 0; i < n; i++) {
      double yPred = m * x[i] + b;
      totalError += pow(yPred - y[i], 2);
    }
    return totalError / (2 * n);
  }

  // Gradient descent loop
  for (int iter = 0; iter < iterations; iter++) {
    double mGrad = 0.0;
    double bGrad = 0.0;

    // Compute gradients
    for (int i = 0; i < n; i++) {
      double yPred = m * x[i] + b;
      double error = yPred - y[i];
      mGrad += error * x[i];
      bGrad += error;
    }

    // Update parameters
    m -= (learningRate * mGrad) / n;
    b -= (learningRate * bGrad) / n;

    // Log progress every 100 iterations
    if (iter % 100 == 0) {
      print('Iteration $iter | '
            'Cost: ${computeCost().toStringAsFixed(4)} | '
            'm: ${m.toStringAsFixed(4)} | '
            'b: ${b.toStringAsFixed(4)}');
    }
  }

  print('\nTrained model parameters:');
  print('  m (slope)     = ${m.toStringAsFixed(4)}');
  print('  b (intercept) = ${b.toStringAsFixed(4)}');

  // Make some predictions
  List<double> testX = [0, 6, 10];
  for (var tx in testX) {
    double pred = m * tx + b;
    print('Prediction for x = $tx: y = ${pred.toStringAsFixed(4)}');
  }
}

