    for (int i = 0; i < N; i++) {
      // Teleportation contribution
      newRank[i] = (1.0 - dampingFactor) / N;
      // Spread sink PR evenly
      newRank[i] += dampingFactor * sinkPR / N;
      // Sum contributions from incoming links (only from nodes with out-links)
