@pragma('vm:entry-point')
void main() {
  // A simple sync* generator that yields numbers from 1 to n.
  Iterable<int> countTo(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i;
    }
  }

  // A sync* generator that yields the first `terms` Fibonacci numbers.
  Iterable<int> fibonacci(int terms) sync* {
    int a = 0, b = 1;
    for (int i = 0; i < terms; i++) {
      yield a;
      int next = a + b;
      a = b;
      b = next;
    }
  }

  // Demonstrate countTo
  print('Counting to 5:');
  for (var value in countTo(5)) {
    print(value);
  }

  // Demonstrate fibonacci
  print('\nFirst 10 Fibonacci numbers:');
  for (var value in fibonacci(10)) {
    print(value);
  }

  // A generator that combines two others using yield*
  Iterable<int> combined(int n) sync* {
    yield* countTo(n);
    yield* fibonacci(n);
  }

  // Demonstrate combined
  print('\nCombined sequence (countTo(3) then fibonacci(3)):');
  for (var value in combined(3)) {
    print(value);
  }
}

